const formatDate = (value?: string) => value ? new Intl.DateTimeFormat("en-SG", { dateStyle: "medium", timeStyle: "short", timeZone: "Asia/Singapore" }).format(new Date(value)) : "Not recorded";
const statusTone = (status: PermitStatus) => ["APPROVED", "ACTIVE", "CLOSED"].includes(status) ? "good" : ["REJECTED", "CANCELLED", "EXPIRED"].includes(status) ? "bad" : ["DRAFT", "SUPERSEDED"].includes(status) ? "neutral" : "warn";
const displayStatus = (status: PermitStatus) => status === "INDIVIDUAL_REVIEW" ? "Pending Individual Reviewer approval" : status === "MT_REVIEW" ? "Pending MT Group approval" : status === "PM_REVIEW" ? "Pending PM approval" : STATUS_LABELS[status];
const permitTypeLabel = (permit: Permit) => permit.type === "HOT_WORK" ? "Hot Work Permit" : "General Permit to Work";
const permitCode = (permit: Permit) => permit.type === "HOT_WORK" ? "HW" : "G";
const canCreatePermit = (user: User) => ["CONTRACTOR_REQUESTOR", "MICRON_STAFF", "SUPER_ADMIN"].includes(user.role);
const canConfigure = (user: User) => ["SUPER_ADMIN", "USER_ADMIN"].includes(user.role);
const canViewReporting = (user: User) => canConfigure(user) || user.role === "MICRON_SUPERVISOR";
const formatDay = (value?: string) => value ? new Intl.DateTimeFormat("en-SG", { day: "numeric", month: "short", year: "numeric", timeZone: "Asia/Singapore" }).format(new Date(value)) : "—";
const singaporeDateOffset = (days: number, reference = new Date()) => {
  const parts = new Intl.DateTimeFormat("en", { year: "numeric", month: "2-digit", day: "2-digit", timeZone: "Asia/Singapore" }).formatToParts(reference);
  const part = (type: Intl.DateTimeFormatPartTypes) => Number(parts.find((item) => item.type === type)?.value);
  const shifted = new Date(Date.UTC(part("year"), part("month") - 1, part("day") + days));
  return `${shifted.getUTCFullYear()}-${String(shifted.getUTCMonth() + 1).padStart(2, "0")}-${String(shifted.getUTCDate()).padStart(2, "0")}`;
};

