function SitesPage() {
  const { user } = useApp(); const [sites, setSites] = useState<SiteRecord[]>(readSites); const [query, setQuery] = useState(""); const [sort, setSort] = useState<"name" | "code">("name"); const [ascending, setAscending] = useState(true); const [page, setPage] = useState(1); const [pageSize, setPageSize] = useState(10); const [adding, setAdding] = useState(false); const [form, setForm] = useState({ name: "", code: "", address: "" });
  if (!canConfigure(user)) return <Navigate to="/dashboard" replace />;
  const saveSites = (next: SiteRecord[]) => { setSites(next); localStorage.setItem(SITE_STORAGE, JSON.stringify(next)); };
  const filtered = sites.filter((site) => `${site.name} ${site.code} ${site.address}`.toLowerCase().includes(query.toLowerCase())).sort((a, b) => (ascending ? 1 : -1) * a[sort].localeCompare(b[sort])); const pages = Math.max(1, Math.ceil(filtered.length / pageSize)); const currentPage = Math.min(page, pages); const visible = filtered.slice((currentPage - 1) * pageSize, currentPage * pageSize);
  const organization = "Micron Semiconductor Asia Pte Ltd";
  const addressFrequency = sites.reduce<Record<string, number>>((counts, site) => ({ ...counts, [site.address]: (counts[site.address] ?? 0) + 1 }), {});
  const primaryAddress = Object.entries(addressFrequency).sort(([, left], [, right]) => right - left)[0]?.[0] ?? "";
  const siteLabel = (site: SiteRecord) => site.name.replace(`${organization} - `, "");
  const addressGroups = Object.entries(visible.reduce<Record<string, SiteRecord[]>>((groups, site) => ({ ...groups, [site.address]: [...(groups[site.address] ?? []), site] }), {})).sort(([left], [right]) => left === primaryAddress ? -1 : right === primaryAddress ? 1 : left.localeCompare(right));
  const existingAddresses = [...new Set(sites.map((site) => site.address))].sort();
  const addToAddressGroup = (address: string) => { setForm({ name: "", code: "", address }); setAdding(true); setTimeout(() => document.querySelector<HTMLInputElement>(".site-form input")?.focus(), 0); };
  const changeSort = (field: "name" | "code") => { if (sort === field) setAscending(!ascending); else { setSort(field); setAscending(true); } };
  const submit = (event: React.FormEvent) => { event.preventDefault(); if (!form.name.trim() || !form.code.trim() || !form.address.trim()) return; saveSites([...sites, { id: crypto.randomUUID(), name: form.name.trim(), code: form.code.trim().toUpperCase(), address: form.address.trim(), createdAt: new Date().toISOString() }]); setForm({ name: "", code: "", address: "" }); setAdding(false); };
  return <div className="page sites-page"><PageHeader eyebrow="System management" title="Sites" text="Manage the locations available for permit applications." action={<button className="button primary" onClick={() => setAdding(true)}>＋ Add site</button>} /><section className="card sites-workspace"><div className="sites-toolbar"><label className="search"><span>⌕</span><input aria-label="Search sites" value={query} onChange={(event) => { setQuery(event.target.value); setPage(1); }} placeholder="Search site name, code or address" /></label><span className="result-count">{filtered.length} site{filtered.length === 1 ? "" : "s"}</span></div>
    {adding && <form className="site-form" onSubmit={submit}><div className="site-form-head"><div><h2>Add site</h2><p>Create a location that can be selected in permit applications.</p></div><button type="button" aria-label="Close form" onClick={() => setAdding(false)}>×</button></div><div className="site-form-grid"><Field label="Site name"><input required value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} placeholder="e.g. Fab 10A3" /></Field><Field label="Site code"><input required maxLength={12} value={form.code} onChange={(event) => setForm({ ...form, code: event.target.value })} placeholder="e.g. F10A3" /></Field><Field label="Site address"><input required list="existing-site-addresses" value={form.address} onChange={(event) => setForm({ ...form, address: event.target.value })} placeholder="Select or enter an address" /><datalist id="existing-site-addresses">{existingAddresses.map((address) => <option value={address} key={address} />)}</datalist></Field></div><div className="site-form-actions"><button type="button" className="button ghost" onClick={() => setAdding(false)}>Cancel</button><button className="button primary" type="submit">Save site</button></div></form>}
    <div className="sites-table-wrap">{visible.length > 0 && <div className="site-organization-header"><div><span className="site-org-mark" aria-hidden="true">M</span><span><strong>{organization}</strong><small>Sites grouped by physical address</small></span></div><b>{filtered.length} sites</b></div>}<table className="sites-table grouped-sites-table"><thead><tr><th><button onClick={() => changeSort("name")}>Site name <span>{sort === "name" ? ascending ? "↑" : "↓" : "↕"}</span></button></th><th><button onClick={() => changeSort("code")}>Site code <span>{sort === "code" ? ascending ? "↑" : "↓" : "↕"}</span></button></th></tr></thead>{addressGroups.map(([address, groupedSites]) => <tbody className={address === primaryAddress ? "primary-address-group" : "alternate-address-group"} key={address}><tr className="site-address-header"><th colSpan={2}><div><span className="address-pin" aria-hidden="true">⌖</span><span><strong>{address}</strong><small>{address === primaryAddress ? "Primary address" : "Alternate address"}</small></span></div><span className="address-group-actions"><b>{groupedSites.length} site{groupedSites.length === 1 ? "" : "s"}</b><button type="button" aria-label={`Add site to ${address}`} title="Add site to this address" onClick={() => addToAddressGroup(address)}>＋</button></span></th></tr>{groupedSites.map((site) => <tr className="site-child-row" key={site.id}><td><strong>{siteLabel(site)}</strong></td><td><b className="site-code">{site.code}</b></td></tr>)}</tbody>)}</table>{!visible.length && <Empty title="No sites found" text="Try changing your search." compact />}</div>
    <div className="sites-pagination"><span>Showing {(currentPage - 1) * pageSize + (visible.length ? 1 : 0)}–{(currentPage - 1) * pageSize + visible.length} of {filtered.length}</span><div><button aria-label="Previous page" disabled={currentPage === 1} onClick={() => setPage(currentPage - 1)}>‹</button><b>{currentPage}</b><button aria-label="Next page" disabled={currentPage === pages} onClick={() => setPage(currentPage + 1)}>›</button><select aria-label="Rows per page" value={pageSize} onChange={(event) => { setPageSize(Number(event.target.value)); setPage(1); }}><option value="10">10 / page</option><option value="20">20 / page</option><option value="50">50 / page</option></select><label>Go to <input aria-label="Go to page" type="number" min="1" max={pages} value={currentPage} onChange={(event) => setPage(Math.max(1, Math.min(pages, Number(event.target.value))))} /></label></div></div>
  </section></div>;
}

