function TutorialLibraryPage() {
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState<"All" | TutorialResource["category"]>("All");
  const visible = TUTORIAL_RESOURCES.filter((tutorial) => (category === "All" || tutorial.category === category) && `${tutorial.number} ${tutorial.title} ${tutorial.category}`.toLowerCase().includes(query.toLowerCase()));
  return <div className="page tutorials-page"><PageHeader eyebrow="Help & resources" title="Tutorial videos" text="Learn the ePTW workflow through short, task-focused walkthroughs." /><section className="card tutorial-toolbar"><label className="search"><span>⌕</span><input aria-label="Search tutorial videos" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search tutorials or permit types" /></label><div className="tutorial-filters" role="group" aria-label="Filter tutorials by category">{(["All", "Getting started", "Permit types", "Workflow"] as const).map((item) => <button type="button" className={category === item ? "active" : ""} aria-pressed={category === item} onClick={() => setCategory(item)} key={item}>{item}</button>)}</div></section>{!query && category === "All" && <section className="tutorial-featured"><div className="tutorial-featured-visual"><span className="tutorial-play" aria-hidden="true">▶</span><small>01</small></div><div><span className="tutorial-eyebrow">Start here</span><h2>Introduction to ePTW</h2><p>Get familiar with the permit workspace, navigation, and the complete controlled-work lifecycle.</p><a href="/tutorial#intro">Watch introduction <span aria-hidden="true">→</span></a></div></section>}<div className="tutorial-results-heading"><div><h2>All tutorials</h2><p>Choose a topic to open its guided walkthrough.</p></div><span>{visible.length} video{visible.length === 1 ? "" : "s"}</span></div>{visible.length ? <section className="tutorial-grid">{visible.map((tutorial) => <article className="tutorial-card" key={tutorial.id}><div className="tutorial-thumbnail"><span aria-hidden="true">▶</span><b>{tutorial.number}</b></div><div className="tutorial-card-body"><span className="tutorial-category">{tutorial.category}</span><h3>{tutorial.title}</h3><p>Updated {tutorial.updated}</p><a href={`/tutorial#${tutorial.id}`} aria-label={`Watch ${tutorial.title}`}>Watch tutorial <span aria-hidden="true">→</span></a></div></article>)}</section> : <section className="card"><Empty title="No tutorials found" text="Try another search term or category." compact /></section>}</div>;
}
function ModulePage({ title, text }: { title: string; text: string }) { const location = useLocation(); if (title === "Analytics") return <AnalyticsPage />; if (title === "Child permits") return <PermitList permitType="HOT_WORK" />; if (title === "LSS / FAS permits") return <LssFasPage />; if (title === "SIPP Daily Report") return <SippReportPage />; if (title === "Drafts") return <Navigate to="/permits" replace />; const resource = new URLSearchParams(location.search).get("resource"); if (resource === "forms") return <FormDownloadsPage />; if (resource === "tutorials") return <TutorialLibraryPage />; const resourceContent = resource === "issue" ? { title: "Report issue", text: "Report a system problem or request support from the ePTW administration team." } : undefined; const pageTitle = resourceContent?.title ?? title; const pageText = resourceContent?.text ?? text; return <div className="page"><PageHeader eyebrow={resourceContent ? "Resources" : "ePTW workspace"} title={pageTitle} text={pageText} /><section className="card"><Empty title={`${pageTitle} module`} text="This navigation destination is reserved for the next functional draft increment." /></section></div>; }
function Empty({ title, text, compact }: { title: string; text: string; compact?: boolean }) { return <div className={`empty ${compact ? "compact" : ""}`}><b>◇</b><strong>{title}</strong><span>{text}</span></div>; }

function AuthenticatedRoutes() { const { user } = useApp(); return <Shell><Routes><Route path="/" element={<Navigate to="/dashboard" replace />} /><Route path="/dashboard" element={<Dashboard />} /><Route path="/permits" element={<PermitList />} /><Route path="/permits/new" element={<PermitFormPage />} /><Route path="/permits/:id/edit" element={<PermitFormPage />} /><Route path="/permits/:id" element={<PermitDetail />} /><Route path="/audit" element={<AuditPage />} /><Route path="/account" element={<AccountSettings />} /><Route path="/help" element={<ModulePage title="Help & resources" text="Guidance, permit procedures, and support contacts." />} /><Route path="/child-permits" element={<PermitList permitType="HOT_WORK" />} /><Route path="/drafts" element={<ModulePage title="Drafts" text="Incomplete permits owned by the current user." />} /><Route path="/lss-fas-permits" element={<ModulePage title="LSS / FAS permits" text="Life-safety and fire-alarm system permit register." />} /><Route path="/submitted-permits" element={<ModulePage title="Parent permits" text="Permits created by the current reviewer." />} /><Route path="/other-permits" element={<ModulePage title="Other permits" text="Permits visible outside the current user's submissions." />} /><Route path="/closure-cancellation" element={<ModulePage title="Closure & cancellation" text="Operational permits awaiting closure or cancellation action." />} /><Route path="/approval-history" element={<ModulePage title="Approval history" text="Completed decisions for the current reviewer." />} /><Route path="/child-approvals" element={<ModulePage title="Child permit approvals" text="Linked child permits requiring review." />} /><Route path="/analytics" element={canViewReporting(user) ? <ModulePage title="Analytics" text="Review permit volumes, status trends, approval performance, and operational insights." /> : <Navigate to="/dashboard" replace />} /><Route path="/sipp-daily-report" element={canViewReporting(user) ? <ModulePage title="SIPP Daily Report" text="Review daily SIPP activity and controlled-work reporting across sites." /> : <Navigate to="/dashboard" replace />} /><Route path="/settings/companies" element={<CompanyListPage user={user} />} /><Route path="/settings/sites" element={<SitesPage />} /><Route path="/settings/maps" element={<MapsPage user={user} />} /><Route path="/settings/users" element={<UsersPage user={user} />} /><Route path="/settings/templates/new" element={<TemplateBuilderPage user={user} createMode />} /><Route path="/settings/templates/:templateId/edit" element={<TemplateBuilderPage user={user} editMode />} /><Route path="/settings/templates" element={<TemplatePage />} /><Route path="/settings/disciplines" element={<DisciplinesPage user={user} />} /><Route path="/settings/mt-groups" element={<MtGroupsPage user={user} />} /><Route path="*" element={<Navigate to="/dashboard" replace />} /></Routes></Shell>; }

export default function App() {
  const storedId = localStorage.getItem("eptw-demo-user");
  const [user, setUserState] = useState<User | null>(() => storedId ? findUser(storedId) : null);
  const [tick, setTick] = useState(0);
  const loginDemo = (next: User) => { localStorage.setItem("eptw-demo-user", next.id); setUserState(next); };
  const registerTemporary = (next: User) => { localStorage.removeItem("eptw-demo-user"); setUserState(next); };
  const logout = () => { localStorage.removeItem("eptw-demo-user"); setUserState(null); };
  return <Routes>
    <Route path="/login" element={<LoginPage user={user} onDemoLogin={loginDemo} />} />
    <Route path="/register/micron" element={<MicronRegistrationPage user={user} onRegister={registerTemporary} />} />
    <Route path="/register/contractor" element={<ContractorRegistrationPage user={user} onRegister={registerTemporary} />} />
    <Route path="/tutorial" element={<TutorialPage user={user} />} />
    <Route path="*" element={user ? <AppContext.Provider value={{ user, setUser: loginDemo, logout, tick, refresh: () => setTick((n) => n + 1) }}><AuthenticatedRoutes /></AppContext.Provider> : <Navigate to="/login" replace />} />
  </Routes>;
}
